# Step 1: Define Shape parent class
class Shape:
    def area(self):
        print("Cannot calculate area for generic shape.")
        return 0

# Steps 2-3: Define Circle class
class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return 3.14 * (self.radius ** 2)

# Steps 4-5: Define Square class
class Square(Shape):
    def __init__(self, side_length):
        self.side_length = side_length

    def area(self):
        return self.side_length ** 2

# Step 6: Create instances (already done)
c1 = Circle(5)
s1 = Square(4)

# Step 7: Create shapes list (already done)
shapes = [c1, s1]

# Step 8: Define print_area function
def print_area(shape):
    print(f"Area: {shape.area()}")

# Step 9: Call print_area on both instances
print_area(c1)
print_area(s1)

